import{z as A,x as n,o as e,c as i,q as r,j as l,D as E,d as B,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"线性扫描寄存器分配","description":"","frontmatter":{"title":"线性扫描寄存器分配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linear-scan-regalloc.md","filePath":"cs/linear-scan-regalloc.md","lastUpdated":1791063341000}'),d={name:"cs/linear-scan-regalloc.md"};function p(c,a,h,m,C,_){const t=n("Mermaid");return e(),i("div",null,[a[2]||(a[2]=r('<h1 id="线性扫描寄存器分配" tabindex="-1">线性扫描寄存器分配 <a class="header-anchor" href="#线性扫描寄存器分配" aria-label="Permalink to &quot;线性扫描寄存器分配&quot;">​</a></h1><div class="epigraph"><p>按活跃区间在线性序上扫描：遇起点分配，遇终点释放；冲突则溢出区间最短或最便宜的。一次扫描，适合 JIT。</p><footer>—— 据 Poletto and Sarkar, Linear Scan Register Allocation, 1999；Wimmer and Mössenböck 的 SSA 线性扫描；对照 Chaitin 整理</footer></div><p>上一课<a href="/cs/fast-math">fast-math</a>收束中端契约。主干<a href="/cs/regalloc-color">寄存器着色</a>已给冲突图。缺口是<strong>更快的分配</strong>：线性扫描用活跃区间（start,end），不建完整冲突图。后端单元第一课。本课钉扫描与溢出启发，精确着色下一课对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色质量好、JIT 里太慢。线性扫描：指令编号后，每个虚寄存器一个区间（SSA 上可拆成短区间）。维护当前活跃集合，大小超过 \\(K\\) 则溢出。缺口是<strong>区间近似</strong>，不是图着色 NP 叙述。</p><p>SSA 线性扫描（Wimmer）：φ 与短区间提高精度，接近着色。</p><h3 id="区间不是「源码作用域」" tabindex="-1">区间不是「源码作用域」 <a class="header-anchor" href="#区间不是「源码作用域」" aria-label="Permalink to &quot;区间不是「源码作用域」&quot;">​</a></h3><p>活跃性来自数据流，不是 C 的花括号。空洞（中间不活跃）可拆区间减冲突——裂变，后课拆分。</p><p><span class="marginnote">Poletto–Sarkar 1999。HotSpot/V8 用线性扫描家族。Appel 以着色为主。本课 JIT 动机明确，AOT 亦可。</span></p><p><span class="marginnote">「活跃区间」就是每个虚寄存器从首次定义到最后一次使用的闭区间 [start, end]：不重叠的区间可共用同一个物理寄存器。线性扫描省掉完整冲突图，用「排序后一次扫描」近似回答「谁和谁冲突」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编号指令。算区间。按起点排序。扫描：释放已结束，分配空物理寄存器，否则选溢出。调用点：caller-save 区间要跨调用则保存或不用该类寄存器。</p><p><span class="marginnote">数字实例：目标机有 \\(K=4\\) 个可用寄存器，第 10 条指令处有 5 个区间同时活跃，必须溢出一个——赶走只活 3 条指令的短区间只需一次 load/store，赶走活 200 条指令的长区间则处处插访存，「溢出最便宜者」就是这么算的。</span></p>',13)),(e(),l(s,null,{default:E(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIVE%5B%22%E6%B4%BB%E8%B7%83%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SCAN%5B%22%E6%8C%89%E8%B5%B7%E7%82%B9%E6%89%AB%E6%8F%8F%22%5D%0A%20%20SCAN%20--%3E%20ASG%5B%22%E5%88%86%E9%85%8D%E6%88%96%E6%BA%A2%E5%87%BA%22%5D%0A%20%20ASG%20--%3E%20REW%5B%22%E6%8F%92%E5%85%A5%20load%2Fstore%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>与<a href="/cs/spill-remat">溢出</a>：重物化（remat）常数比溢出槽便宜，扫描时也可选。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>质量：长区间被溢出可能差于着色。调用密集时线性扫描仍要尊重 ABI。不要跨 <code>call</code> 把 caller-save 当免费。</p><p>与指令调度：先调度再分配或迭代；扫描假设已有序。</p><p><span class="marginnote">常见误区：初学者以为溢出成本只看区间长短。跨 <code>call</code> 的 caller-save 区间还要加保存/恢复指令，常数可重物化（remat）的区间溢出反而更省——「最便宜」要按实际插入的指令数与访存次数合算，不是单纯比长度。</span></p>',5)),(e(),l(s,null,{default:E(()=>[o(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%8C%BA%E9%97%B4%E7%9A%84%E8%B5%B7%E7%82%B9%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20PR%5B%22%E5%85%88%E5%9B%9E%E6%94%B6%E7%BB%88%E7%82%B9%E5%B7%B2%E8%BF%87%E7%9A%84%E5%8C%BA%E9%97%B4%20%E8%85%BE%E5%87%BA%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20PR%20--%3E%20Q%7B%22%E6%9C%89%E7%A9%BA%E9%97%B2%E7%89%A9%E7%90%86%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%9C%89%22%20--%3E%20AL%5B%22%E6%8A%8A%E5%8C%BA%E9%97%B4%E5%88%86%E5%88%B0%E8%AF%A5%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20Q%20--%20%22%E6%97%A0%22%20--%3E%20CMP%7B%22%E8%B0%81%E6%BA%A2%E5%87%BA%E6%9C%80%E4%BE%BF%E5%AE%9C%EF%BC%9F%22%7D%0A%20%20CMP%20--%20%22%E5%BD%93%E5%89%8D%E5%8C%BA%E9%97%B4%E6%9C%80%E4%BE%BF%E5%AE%9C%22%20--%3E%20SP%5B%22%E5%BD%93%E5%89%8D%E5%8C%BA%E9%97%B4%E8%BF%9B%E6%BA%A2%E5%87%BA%E6%A7%BD%22%5D%0A%20%20CMP%20--%20%22%E6%9F%90%E4%B8%AA%E5%9C%A8%E5%86%8C%E5%8C%BA%E9%97%B4%E6%9B%B4%E8%B4%B5%22%20--%3E%20EV%5B%22%E9%A9%B1%E9%80%90%E5%AE%83%20%E5%BD%93%E5%89%8D%E5%8C%BA%E9%97%B4%E9%A1%B6%E4%B8%8A%22%5D%0A%20%20AL%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E6%89%AB%E4%B8%8B%E4%B8%80%E4%B8%AA%E8%B5%B7%E7%82%B9%22%5D%0A%20%20SP%20--%3E%20CONT%0A%20%20EV%20--%3E%20CONT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Chaitin 栈着色细节。后课默认：JIT 可用线性扫描。下一课 Chaitin–Briggs：图着色经典。</p><p>也不把线性扫描当磁盘调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性扫描：活跃区间 + 一次扫描分配。</li><li>快、适合 JIT；质量通常低于精细着色。</li><li>SSA 短区间可改善。</li><li>出处：Poletto and Sarkar, 1999；Wimmer–Mössenböck；对照 Chaitin。</li></ul>',5))])}const T=A(d,[["render",p]]);export{D as __pageData,T as default};
